game.preface:

      // this class handles deleting stuff from a players hand.
      // if validateweight is true, class will validate that the deletion put them below
      // their hand limit.
      // if false, class will validate that the deletion spent at least i_cost, and at least i_numresearch.
      class HandDeleter
      {
      public:
        HandDeleter(OutpostGameInfo &i_ogi,Player &i_player,const std::string &i_deletestring,Spend &i_newspend,
	            bool i_validateweight,int i_cost = 0, int i_numresearch = 0)
	{
	  std::vector<Commodity> deletedItems;
	  CommodityHand newhand = i_player.GetCommodityHand();
	  int origover = newhand.GetHandWeight(i_ogi.GetOptions().GetResearchIsSmall(),i_ogi.GetOptions().GetMicroIsSmall())
	               - i_player.GetHandLimit(i_ogi.GetOptions().GetEarlyDiscard());

	  int result = newhand.ApplyDeletes(i_deletestring,deletedItems);
	  switch(result)
          {
	  case -1: throw GameActionError("Mismatched delete string length");
	  case -2: throw GameActionError("Illegal characters in delete string");
	  case 0: break; // this is the ok case.
	  default: throw GameActionError("Unknown error reported by ApplyDeletes");
	  }

	  if (i_validateweight)
	  {
	    i_newspend.SetSpendCost(origover);

	    int over = newhand.GetHandWeight(i_ogi.GetOptions().GetResearchIsSmall(),i_ogi.GetOptions().GetMicroIsSmall())
	               - i_player.GetHandLimit(i_ogi.GetOptions().GetEarlyDiscard());

	    if (over > 0)
	    {
	      throw GameActionError("You need to discard more to get to your hand limit.");
	    }
          }
	  else
	  {
            i_newspend.SetSpendCost(i_cost);
	    if (i_player.GetCommodityHand().GetHandValue() - newhand.GetHandValue() < i_cost)
	    {
	      throw GameActionError("You need to spend more to buy that.");
	    }
	    if (i_player.GetCommodityHand().GetNumResearch() - newhand.GetNumResearch() < i_numresearch)
	    {
	      throw GameActionError("You need to spend more Research resource cards to buy that.");
	    }
          }

	  // if we got here, we can safely discard the cards and make the new hand the player's hand.
	  size_t i;
	  for (i = 0 ; i < deletedItems.size() ; ++i)
	  {
	    i_ogi.GetCommodities().GetDeck(deletedItems[i].GetType()).DiscardCommodity(deletedItems[i]);
	    i_newspend.AddCommodity(deletedItems[i]);

	  }
	  i_player.GetCommodityHand() = newhand;
        }
      };

transition.body:

        size_t i;
        for (i = 0 ; i < GetPlayers().size() ; ++i)
	{
	  GetPlayers()[i].SetOkStartup(false);
	}


        SetCurTurn(1);
	GetCommodities().ApplyResearchMegaStatus(GetOptions().GetResearchMega());
	GetUnownedItems().Initialize(GetPlayers().size(),GetOptions().GetStockMechanism());
	size_t i;
	for (i = 0 ; i < GetPlayers().size() ; ++i)
	{
	  GetPlayers()[i].GetFactories().AddFactory(ORE_FACTORY);
	  GetPlayers()[i].GetFactories().AddFactory(ORE_FACTORY);
	  GetPlayers()[i].GetFactories().AddFactory(WATER_FACTORY);
	  GetPlayers()[i].GetFactories().AlterManning("HHH",3,0);
	  GetPlayers()[i].AddHumans(STARTHUMANS);
	}


      Spend spend(GetCurTurn(),
                  GetPlayers().GetCurTurnPlayer().GetId(),
		  DISCARD,
		  0
		  );

      HandDeleter hd(*this,GetPlayers().GetCurTurnPlayer(),i_discardstring,spend,true);

      GetSpends().push_back(spend);


      GetPlayers().IncrementTurnOrder();


        Spend spend(GetCurTurn(),
	            GetPlayers().GetPlayerByName(i_PlayerName).GetId(),
		    ITEMPURCHASE,
		    MAN_PURCHASABLE
		    );

        HandDeleter hd(*this,GetPlayers().GetPlayerByName(i_PlayerName),i_discardstring,spend,false,
	               i_nummen * GetPlayers().GetPlayerByName(i_PlayerName).GetOwnedItems().GetPeopleCost());

	GetSpends().push_back(spend);
	GetPlayers().GetPlayerByName(i_PlayerName).AddHumans(i_nummen);
	GetPlayers().GetPlayerByName(i_PlayerName).AutoMan();


        Spend spend(GetCurTurn(),
	            GetPlayers().GetPlayerByName(i_PlayerName).GetId(),
		    ITEMPURCHASE,
		    ROBOT_PURCHASABLE
		    );

        HandDeleter hd(*this,GetPlayers().GetPlayerByName(i_PlayerName),i_discardstring,spend,false,i_numrobots * 10);

	GetSpends().push_back(spend);

	GetPlayers().GetPlayerByName(i_PlayerName).AddRobots(i_numrobots);
	GetPlayers().GetPlayerByName(i_PlayerName).AutoMan();


        Spend spend(GetCurTurn(),
	            GetPlayers().GetPlayerByName(i_PlayerName).GetId(),
		    ITEMPURCHASE,
		    ORE_FACTORY_PURCHASABLE
		    );

        HandDeleter hd(*this,GetPlayers().GetPlayerByName(i_PlayerName),i_discardstring,spend,false,i_numfactories * 10);

	GetSpends().push_back(spend);

	for (int i = 0 ; i < i_numfactories ; ++i)
	{
	  GetPlayers().GetPlayerByName(i_PlayerName).GetFactories().AddFactory(ORE_FACTORY);
	}

	GetPlayers().GetPlayerByName(i_PlayerName).AutoMan();


        Spend spend(GetCurTurn(),
	            GetPlayers().GetPlayerByName(i_PlayerName).GetId(),
		    ITEMPURCHASE,
		    WATER_FACTORY_PURCHASABLE
		    );

        HandDeleter hd(*this,GetPlayers().GetPlayerByName(i_PlayerName),i_discardstring,spend,false,i_numfactories * 20);

	GetSpends().push_back(spend);

	for (int i = 0 ; i < i_numfactories ; ++i)
	{
	  GetPlayers().GetPlayerByName(i_PlayerName).GetFactories().AddFactory(WATER_FACTORY);
	}

	GetPlayers().GetPlayerByName(i_PlayerName).AutoMan();


        Spend spend(GetCurTurn(),
	            GetPlayers().GetPlayerByName(i_PlayerName).GetId(),
		    ITEMPURCHASE,
		    TITANIUM_FACTORY_PURCHASABLE
		    );

        HandDeleter hd(*this,GetPlayers().GetPlayerByName(i_PlayerName),i_discardstring,spend,false,i_numfactories * 30);

	GetSpends().push_back(spend);

	for (int i = 0 ; i < i_numfactories ; ++i)
	{
	  GetPlayers().GetPlayerByName(i_PlayerName).GetFactories().AddFactory(TITANIUM_FACTORY);
	}

	GetPlayers().GetPlayerByName(i_PlayerName).AutoMan();


        Spend spend(GetCurTurn(),
	            GetPlayers().GetPlayerByName(i_PlayerName).GetId(),
		    ITEMPURCHASE,
		    RESEARCH_FACTORY_PURCHASABLE
		    );

        HandDeleter hd(*this,GetPlayers().GetPlayerByName(i_PlayerName),i_discardstring,spend,false,i_numfactories * 40);

	GetSpends().push_back(spend);

	for (int i = 0 ; i < i_numfactories ; ++i)
	{
	  GetPlayers().GetPlayerByName(i_PlayerName).GetFactories().AddFactory(RESEARCH_FACTORY);
	}

	GetPlayers().GetPlayerByName(i_PlayerName).AutoMan();


        Spend spend(GetCurTurn(),
	            GetPlayers().GetPlayerByName(i_PlayerName).GetId(),
		    ITEMPURCHASE,
		    NEW_CHEMICALS_FACTORY_PURCHASABLE
		    );

        HandDeleter hd(*this,GetPlayers().GetPlayerByName(i_PlayerName),
	               i_discardstring,spend,false,i_numfactories * 60,i_numfactories);

	GetSpends().push_back(spend);

	for (int i = 0 ; i < i_numfactories ; ++i)
	{
	  GetPlayers().GetPlayerByName(i_PlayerName).GetFactories().AddFactory(NEW_CHEMICALS_FACTORY);
	}

	GetPlayers().GetPlayerByName(i_PlayerName).AutoMan();


        Spend spend(GetCurTurn(),
	            GetPlayers().GetPlayerByName(i_PlayerName).GetId(),
		    WATERMULLIGAN,
		    WATER_FACTORY_PURCHASABLE
		    );
	spend.SetSpendCost(0);

        size_t i;
	for (i = 0 ; i < GetPlayers().GetPlayerByName(i_PlayerName).GetCommodityHand().GetHand().size() ; ++i)
	{
	  Commodity c = GetPlayers().GetPlayerByName(i_PlayerName).GetCommodityHand().GetHand()[i];
	  GetCommodities().GetDeck(c.GetType()).DiscardCommodity(c);
	  spend.AddCommodity(c);	  
	}
	GetPlayers().GetPlayerByName(i_PlayerName).GetCommodityHand() = CommodityHand();
	GetPlayers().GetPlayerByName(i_PlayerName).GetFactories().AddFactory(WATER_FACTORY);

	GetSpends().push_back(spend);

	GetPlayers().GetPlayerByName(i_PlayerName).AutoMan();


        GetPlayers().StartBidPhase(GetOptions().GetMustBeActiveToBid(),GetOptions().GetOneUpgradePerTurn(),i_openingbid);
	GetUnownedItems().SetBidIndex(i_shipslot);

	size_t i;
	for (i = 0; i < GetPlayers().size() ; ++i)
	{	
	  GetPlayers()[i].SetLastBid(NOT_HIGH_BID);
	  if (GetPlayers()[i].GetHighBid() != NOT_HIGH_BID)
	  {
	    GetPlayers()[i].SetLastBid(GetPlayers()[i].GetHighBid());
	  }
	}


        Player &pl = GetPlayers().GetPlayerByName(i_PlayerName);
	int result = pl.GetFactories().AlterManning(i_manningstring,pl.GetNumHumans(),pl.GetNumRobots());
	switch(result)
	{
	case -4: throw GameActionError("Removing Man from Mannable Item");
	case -3: throw GameActionError("Invalid Character in Manning List");
	case -2: throw GameActionError("Too Many Robots or People");
	case -1: throw GameActionError("Invalid Length of Manning List");
	}


Player &oldpl = GetPlayers().GetCurTurnPlayer();

if (oldpl.GetMaxHumans() < oldpl.GetNumHumans())
{
  oldpl.AddHumans( -1 * (oldpl.GetNumHumans() - oldpl.GetMaxHumans() ) );
}

if (oldpl.GetMaxRobots(GetOptions().GetRobotMechanism()) != UNLIMITED_ROBOTS &&
    oldpl.GetMaxRobots(GetOptions().GetRobotMechanism()) < oldpl.GetNumRobots())
{
  oldpl.AddRobots( -1 * (oldpl.GetNumRobots() - oldpl.GetMaxRobots(GetOptions().GetRobotMechanism()) ) );
}

GetPlayers().IncrementManningTurnOrder();


        Spend spend(GetCurTurn(),
                    GetPlayers().GetCurBidPlayer().GetId(),
		    BIDPURCHASE,
		    GetUnownedItems().GetShipItem(GetUnownedItems().GetBidIndex())
		    );

        HandDeleter hd(*this,GetPlayers().GetCurBidPlayer(),
	               i_discardstring,spend,false,GetPlayers().GetCurBidPlayer().GetHighBid() - 
		                                   GetPlayers().GetCurBidPlayer().GetOwnedItems().GetDiscount(
					             GetUnownedItems().GetShipItem(GetUnownedItems().GetBidIndex())),0);

	GetSpends().push_back(spend);

	Player &pl = GetPlayers().GetCurBidPlayer();
	size_t itemindex = GetUnownedItems().GetBidIndex();
	ItemType curitem = GetUnownedItems().GetShipItem(itemindex);

	int finalcost = pl.GetHighBid() - pl.GetOwnedItems().GetDiscount(curitem);

	FactoryType newfac = pl.GetOwnedItems().AddItem(GetUnownedItems().GetShipItem(GetUnownedItems().GetBidIndex()));
	if (newfac != NO_FACTORY) pl.GetFactories().AddFactory(newfac);

	pl.SetHighBid(NOT_HIGH_BID);
	pl.SetHasPurchased(true);
	pl.SetBidState(PASS_OUT);


	GetUnownedItems().SetPurchased(itemindex,curitem,pl.GetId(),finalcost);
	GetUnownedItems().SetShipItem(GetUnownedItems().GetBidIndex(),NO_ITEM);
	pl.AutoMan();


	GetUnownedItems().SetBidIndex(NO_BID_INDEX);


        SetCurTurn(GetCurTurn() + 1);

	size_t i;
	for (i = 0 ; i < GetPlayers().size() ; ++i)
	{
	  GetPlayers()[i].GetCommodityHand().AgeHand();
	  GetPlayers()[i].SetLastBid(NOT_HIGH_BID);
	  GetPlayers()[i].SetHasPurchased(false);
	}

game.refresh:


boost::json::object options;
options["discard"] = GetOptions().GetEarlyDiscard();
options["refinery"] = GetOptions().GetRefineries();
options["oneupgrade"] = GetOptions().GetOneUpgradePerTurn();
options["activebid"] = GetOptions().GetMustBeActiveToBid();
options["supplyharshness"] = GetOptions().GetSupplyHarshness();
options["robots"] = static_cast<int>(GetOptions().GetRobotMechanism());
options["researchmega"] = GetOptions().GetResearchMega();
options["smallresearch"] = GetOptions().GetResearchIsSmall();
options["smallmicro"] = GetOptions().GetMicroIsSmall();
options["blinddraws"] = GetOptions().GetBlindDraws();
options["stock"] = static_cast<int>(GetOptions().GetStockMechanism());

boost::json::array players;
for (size_t i = 0 ; i < GetPlayers().size() ; ++i)
{
  const Player &p = GetPlayers()[i];
  boost::json::object playerobj;
  playerobj["name"] = p.GetName();
  playerobj["id"] = p.GetId();
  playerobj["okstartup"] = p.OkStartup();

  playerobj["victoryPoints"] = p.GetVP();
  playerobj["itemCostSum"] = p.GetOwnedItems().GetCostSum();
  playerobj["handLimit"] = p.GetHandLimit(GetOptions().GetEarlyDiscard());
  playerobj["popLimit"] = p.GetMaxHumans();
  playerobj["robotLimit"] = p.GetMaxRobots(GetOptions().GetRobotMechanism());
  playerobj["manCost"] = p.GetOwnedItems().GetPeopleCost();
  playerobj["numHumans"] = p.GetNumHumans();
  playerobj["numRobots"] = p.GetNumRobots();
  playerobj["purchaseState"] = static_cast<int>(p.GetPurchaseState());
  playerobj["bidState"] = static_cast<int>(p.GetBidState());
  playerobj["hasPurchased"] = p.HasPurchased();
  playerobj["highBid"] = p.GetHighBid();
  playerobj["lastBid"] = p.GetLastBid();
  playerobj["factoryDescription"] = p.GetFactories().GetFactoryDescription();
  playerobj["cardBackDescription"] = p.GetCommodityHand().GetHandDescription(false,false);

  boost::json::array items;
  const std::vector<ItemType> &itemList = p.GetOwnedItems().GetItemList();
  for (size_t j = 0 ; j < itemList.size() ; ++j)
  {
    items.push_back(static_cast<int>(itemList[j]));
  }
  playerobj["items"] = items;

  players.push_back(playerobj);
}

boost::json::object result;
result["options"] = options;
result["players"] = players;
result["myPlayerId"] = GetPlayers().IsPlayer(i_PlayerName) ?
    boost::json::value(static_cast<int>(GetPlayers().GetPlayerId(i_PlayerName))) :
    boost::json::value(nullptr);

// Unlike every other in-game-only field below, there's no reason this
// one needs to wait for STARTGAME -- it's just empty (rather than
// absent) until GetUnownedItems().Initialize() gives it real slots,
// same shape either way. GetShipItem() itself would throw
// std::out_of_range before Initialize() runs (its backing vector is
// still default-constructed/empty), hence the Initialized() guard.
boost::json::array supplyShip;
if (GetUnownedItems().Initialized())
{
  for (size_t shipIndex = 0 ; shipIndex < GetPlayers().size() ; ++shipIndex)
  {
    supplyShip.push_back(static_cast<int>(GetUnownedItems().GetShipItem(shipIndex)));
  }
}
result["supplyShip"] = supplyShip;

// Same reasoning as supplyShip, but resolved one level down: unlike
// m_SupplyShip, GetUnownedItems()'s m_ItemCount is always a full
// 14-entry, zero-filled vector from construction (see UnownedItems's
// own constructor) regardless of whether the game has started, so
// GetItemCount() is unconditionally safe here -- this loop needs no
// Initialized() guard at all, unlike supplyShip's.
boost::json::array itemStock;
for (int itemType = DATA_LIBRARY ; itemType <= MOON_BASE ; ++itemType)
{
  boost::json::object itemobj;
  itemobj["itemId"] = itemType;
  itemobj["count"] = GetUnownedItems().GetItemCount((ItemType)itemType);
  itemStock.push_back(itemobj);
}
result["itemStock"] = itemStock;

boost::json::array commodityStock;
for (int commType = ORE_COMMODITY ; commType <= MOON_ORE_COMMODITY ; ++commType)
{
  const CommodityDeck &deck = GetCommodities().GetDeck((CommodityType)commType);
  boost::json::object commobj;
  commobj["commodityId"] = commType;
  commobj["drawCount"] = deck.GetDeckSize();
  commobj["discardCount"] = deck.GetDiscardSize();
  commobj["megaValue"] = deck.GetMegaValue();
  commobj["averageValue"] = deck.GetAverageValue();
  commodityStock.push_back(commobj);
}
result["commodityStock"] = commodityStock;

boost::json::array spends;
for (size_t i = 0 ; i < GetSpends().size() ; ++i)
{
  const Spend &s = GetSpends()[i];
  boost::json::object spendobj;
  spendobj["turnNum"] = s.GetTurnNum();
  spendobj["playerId"] = static_cast<int>(s.GetPlayerNum());
  spendobj["spendType"] = static_cast<int>(s.GetSpendType());
  spendobj["spendItem"] = s.GetSpendItem();
  spendobj["spendCost"] = s.GetSpendCost();
  spendobj["resources"] = s.GetCommodityHand().GetHandDescription(true,true);
  spends.push_back(spendobj);
}
result["spends"] = spends;

if (i_StateName == InitialState || i_StateName == ValidateSetup)
{
  return result;
}

result["turnNum"] = GetCurTurn();

boost::json::array turnOrder;
for (size_t i = 0 ; i < GetPlayers().GetTurnOrder().size() ; ++i)
{
  turnOrder.push_back(GetPlayers().GetTurnOrder()[i]);
}
result["turnOrder"] = turnOrder;

result["currentTurnPlayerId"] = GetPlayers().AllPlayersDone() ?
    boost::json::value(nullptr) :
    boost::json::value(static_cast<int>(GetPlayers().GetCurTurnPlayer().GetId()));

result["currentBidderId"] = (i_StateName == Bid) ?
    boost::json::value(static_cast<int>(GetPlayers().GetCurBidPlayer().GetId())) :
    boost::json::value(nullptr);

boost::json::array purchaseData;
for (size_t shipIndex = 0 ; shipIndex < GetPlayers().size() ; ++shipIndex)
{
  const PurchaseInfo &pinfo = GetUnownedItems().GetPurchaseInfo(shipIndex);
  boost::json::object purchaseobj;
  purchaseobj["shipIndex"] = static_cast<int>(shipIndex);
  purchaseobj["playerId"] = static_cast<int>(pinfo.m_playerindex);
  purchaseobj["itemId"] = static_cast<int>(pinfo.m_type);
  purchaseobj["cost"] = pinfo.m_cost;
  purchaseData.push_back(purchaseobj);
}
result["purchaseData"] = purchaseData;

if (GetPlayers().IsPlayer(i_PlayerName))
{
  const Player &me = GetPlayers().GetPlayerByName(i_PlayerName);

  result["myHand"] = me.GetCommodityHand().GetHandDescription(true,
      GetProductionManager().IsProductionDone() || !GetOptions().GetBlindDraws());

  boost::json::object purchaseInfo;
  purchaseInfo["manCost"] = me.GetOwnedItems().GetPeopleCost();
  purchaseInfo["numRobots"] = me.GetMaxPurchasable(ROBOT_PURCHASABLE,GetOptions().GetRobotMechanism());
  purchaseInfo["numMen"] = me.GetMaxPurchasable(MAN_PURCHASABLE,GetOptions().GetRobotMechanism());
  purchaseInfo["numOre"] = me.GetMaxPurchasable(ORE_FACTORY_PURCHASABLE,GetOptions().GetRobotMechanism());
  purchaseInfo["numWater"] = me.GetMaxPurchasable(WATER_FACTORY_PURCHASABLE,GetOptions().GetRobotMechanism());
  purchaseInfo["numTitanium"] = me.GetMaxPurchasable(TITANIUM_FACTORY_PURCHASABLE,GetOptions().GetRobotMechanism());
  purchaseInfo["numResearch"] = me.GetMaxPurchasable(RESEARCH_FACTORY_PURCHASABLE,GetOptions().GetRobotMechanism());
  purchaseInfo["numNewChem"] = me.GetMaxPurchasable(NEW_CHEMICALS_FACTORY_PURCHASABLE,GetOptions().GetRobotMechanism());
  result["myPurchaseInfo"] = purchaseInfo;
}
else
{
  result["myHand"] = nullptr;
  result["myPurchaseInfo"] = nullptr;
}

if (i_StateName == MegaResources && i_PlayerName == GetPlayers().GetCurTurnPlayer().GetName())
{
  boost::json::object megaRequest;
  megaRequest["resourceType"] = static_cast<int>(GetProductionManager().GetMegaInfo().m_Commodity);
  megaRequest["maxMegas"] = GetProductionManager().GetMegaInfo().m_MaxMegas;
  result["megaRequest"] = megaRequest;
}
else
{
  result["megaRequest"] = nullptr;
}

if (i_StateName == Bid)
{
  boost::json::object bidInfo;
  bidInfo["itemShipIndex"] = static_cast<int>(GetUnownedItems().GetBidIndex());
  bidInfo["price"] = GetPlayers().GetHighBidPlayer().GetHighBid() -
      GetPlayers().GetHighBidPlayer().GetOwnedItems().GetDiscount(
          GetUnownedItems().GetShipItem(GetUnownedItems().GetBidIndex()));
  result["bidInfo"] = bidInfo;
}
else
{
  result["bidInfo"] = nullptr;
}

boost::json::array winners;
if (i_StateName == TerminalState)
{
  std::set<size_t> winset = GetPlayers().GetWinningPlayerIndices();
  std::set<size_t>::iterator winit;
  for (winit = winset.begin() ; winit != winset.end() ; ++winit)
  {
    winners.push_back(static_cast<int>(*winit));
  }
}
result["winners"] = winners;

return result;
